const CWLM_N=(()=>{   // 载入即建索引：计数 Map + 上下文总计 + unigram 总
  const n=CWLM.n.map(d=>new Map(Object.entries(d)));
  const tot=[new Map(),new Map(),new Map(),new Map(),new Map()];
  for(let k=2;k<=4;k++) for(const [key,c] of n[k]){
    const ctx=key.slice(0,-1);
    tot[k].set(ctx,(tot[k].get(ctx)||0)+c);
  }
  let tu=0; for(const c of n[1].values()) tu+=c;
  return {n,tot,tu};
})();
function cwLmLP(c, hist){   // log P(c | hist)，stupid backoff 0.4
  const {n,tot,tu}=CWLM_N;
  let pen=0;
  for(let k=4;k>=2;k--){
    const ctx=hist.slice(-(k-1));
    if(ctx.length<k-1) { pen+=Math.log10(0.4); continue; }
    const v=n[k].get(ctx+c);
    if(v){ const t=tot[k].get(ctx)||1; return Math.log(v/t)+pen*0+pen; }
    pen+=Math.log(0.4);
  }
  const v=n[1].get(c)||0.5;
  return Math.log(v/tu)+pen;
}
if(typeof module!=="undefined") module.exports={CWLM,CWLM_N,cwLmLP};
